    // ---- production regions (gates 1f, 21) ----

    #[test]
    fn a_braced_use_under_cfg_test_does_not_swallow_the_next_item() {
        let src = "#[cfg(test)]\nuse std::{fs, io};\n\npub fn production() {\n    let _ = std::fs::File::create(\"x\");\n}\n";
        let code = code_view(src, true).unwrap();
        assert!(code.contains("File::create"));
        assert!(!code.contains("use std::{fs, io}"));
    }

    #[test]
    fn production_after_a_test_module_is_still_production() {
        let src = "#[cfg(test)]\nmod tests {\n    const S: &str = \"<script>in test</script>\";\n}\n\npub fn late() -> &'static str { \"<script>late</script>\" }\n";
        let code = code_view(src, true).unwrap();
        assert!(!code.contains("in test"));
        assert!(code.contains("late</script>"));
    }

    #[test]
    fn cfg_test_items_of_every_shape_end_where_they_should() {
        let src = "#[cfg(test)]\nconst X: [u8; 2] = [1, 2];\nfn a() {}\n#[cfg(test)]\n#[allow(dead_code)]\nstruct S;\nfn b() {}\n#[cfg(test)]\nimpl S { fn c() {} }\nfn d() {}\n#[cfg(test)]\nconst Y: T = T { a: 1 };\nfn e() {}\n";
        let code = code_view(src, true).unwrap();
        for live in ["fn a()", "fn b()", "fn d()", "fn e()"] {
            assert!(code.contains(live), "{live} was blanked");
        }
        for gone in ["[1, 2]", "struct S", "fn c()", "a: 1"] {
            assert!(!code.contains(gone), "{gone} survived");
        }
    }

    #[test]
    fn an_inner_cfg_test_blanks_the_whole_file() {
        let code = code_view("#![cfg(test)]\nfn a() {}\n", true).unwrap();
        assert!(code.trim().is_empty());
    }

    #[test]
    fn a_cfg_test_field_or_arm_ends_at_its_comma() {
        let src = "struct S {\n    #[cfg(test)]\n    t: u8,\n    live: u8,\n}\n";
        let code = code_view(src, true).unwrap();
        assert!(code.contains("live: u8"));
        assert!(!code.contains("t: u8,"));
    }

