    // ---- canonical paths (gates 21, 22) ----

    fn paths(src: &str) -> Vec<String> {
        canonical_paths(src, true)
            .unwrap()
            .into_iter()
            .map(|(_, p)| p)
            .collect()
    }

    #[test]
    fn an_aliased_import_group_is_expanded() {
        let p = paths("use std::{fs as f}; fn g() { f::read(\"x\"); }");
        assert!(p.contains(&"std::fs::read".to_owned()), "{p:?}");
        let p = paths(
            "use std::fs::{self, File}; fn g() { File::create(\"x\"); fs::write(\"a\", \"b\"); }",
        );
        assert!(p.contains(&"std::fs::File::create".to_owned()), "{p:?}");
        assert!(p.contains(&"std::fs::write".to_owned()), "{p:?}");
        let p = paths("use std::fs::*; fn g() {}");
        assert!(p.contains(&"std::fs::*".to_owned()), "{p:?}");
        let p = paths("fn g() { std :: fs :: r#write(\"a\", \"b\"); }");
        assert!(p.contains(&"std::fs::write".to_owned()), "{p:?}");
    }

    #[test]
    fn a_root_path_and_an_aliased_macro_are_paths() {
        let p = paths(
            "use std::eprintln as note; fn g() -> u8 { ::log::info!(\"z\"); note!(\"y\"); return ::std::io::stderr(); }",
        );
        for want in [
            "log::info!",
            "std::eprintln!",
            "std::eprintln",
            "std::io::stderr",
        ] {
            assert!(p.contains(&want.to_owned()), "{want} missing from {p:?}");
        }
        let p = paths("fn g() { a::b::<u8>::c(); x::y(); }");
        assert!(!p.contains(&"c".to_owned()), "{p:?}");
        assert!(!p.contains(&"y".to_owned()), "{p:?}");
        let p = paths("fn g(print: u8, stderr: u8) -> bool { print != stderr }");
        assert!(p.contains(&"print".to_owned()), "{p:?}");
        assert!(!p.iter().any(|s| s.ends_with('!')), "{p:?}");
    }

    #[test]
    fn method_calls_are_not_paths() {
        let p = paths("fn g(x: X) { x.fs::<u8>(); x.write(); }");
        assert!(!p.iter().any(|s| s.contains("write")), "{p:?}");
    }

    // ---- TOML (gates 9, 9b, 13, 22, 25, 1g) ----

    fn deps(src: &str) -> Vec<(String, String, String)> {
        dependencies(src)
            .unwrap()
            .into_iter()
            .map(|(_, k, n, p)| (k, n, p))
            .collect()
    }

    #[test]
    fn every_spelling_cargo_accepts_is_a_dependency() {
        for src in [
            "[dependencies . indicators]\npath = \"../indicators\"\n",
            "dependencies.indicators = { path = \"../indicators\" }\n[package]\nname = \"x\"\n",
            "[\"dependencies\"]\nindicators = { path = \"../indicators\" }\n",
            "[dependencies]\n\"indicators\" = { path = \"../indicators\" }\n",
            "[dependencies]\nindicators . path = \"../indicators\"\n",
            "[dependencies]\nx = { package = 'indicators', path = '../indicators' }\n",
            "[dev-dependencies]\nindicators = \"1\"\n",
            "[dev_dependencies]\nindicators = \"1\"\n",
            "[target.'cfg(unix)'.dependencies]\nindicators = \"1\"\n",
            "dependencies = { indicators = { path = \"../i\" } }\n",
            "[dependencies.\"indicators\"]\n",
        ] {
            let d = deps(src);
            assert!(
                d.iter()
                    .any(|(_, n, p)| n == "indicators" || p == "indicators"),
                "missed: {src} -> {d:?}"
            );
        }
    }

