    // ---- the workflow (gates 13, 14, 0) ----

    const WF: &str = "jobs:\n  build:\n    runs-on: x\n    steps:\n      - name: Gate 3\n        run: |\n          cargo deny check\n  ci-ok:\n    needs: [build]\n    steps:\n      - run: true\n";

    #[test]
    fn an_unconditional_step_is_present() {
        assert_eq!(step_runs(WF, "cargo deny check"), Ok(1));
    }

    #[test]
    fn every_way_to_switch_a_step_off_is_refused() {
        for (from, to) in [
            (
                "      - name: Gate 3\n",
                "      - name: Gate 3\n        continue-on-error: true\n",
            ),
            (
                "      - name: Gate 3\n",
                "      - name: Gate 3\n        if: false && true\n",
            ),
            (
                "      - name: Gate 3\n",
                "      - name: Gate 3\n        if: github.run_attempt == 0\n",
            ),
            (
                "      - name: Gate 3\n",
                "      - name: Gate 3\n        if: steps.probe.outputs.has_crates == 'false'\n",
            ),
            (
                "      - name: Gate 3\n",
                "      - continue-on-error: true\n        name: Gate 3\n",
            ),
            (
                "    runs-on: x\n",
                "    runs-on: x\n    continue-on-error: true\n",
            ),
            ("    runs-on: x\n", "    runs-on: x\n    if: ${{ false }}\n"),
            ("    needs: [build]\n", "    needs: [other]\n"),
            (
                "          cargo deny check\n",
                "          echo cargo deny check\n",
            ),
        ] {
            let wf = WF.replacen(from, to, 1);
            assert!(step_runs(&wf, "cargo deny check").is_err(), "passed: {to}");
        }
    }

    #[test]
    fn always_success_and_not_cancelled_are_safe() {
        for c in [
            "always()",
            "${{ success() }}",
            "!cancelled()",
            "'always()'",
            "steps.probe.outputs.has_crates == 'true'",
        ] {
            let wf = WF.replacen(
                "      - name: Gate 3\n",
                &format!("      - name: Gate 3\n        if: {c}\n"),
                1,
            );
            assert_eq!(step_runs(&wf, "cargo deny check"), Ok(1), "{c}");
        }
    }

    #[test]
    fn workflow_hygiene_refusals() {
        for bad in [
            "      - continue-on-error: true\n",
            "          if printf '%s' \"$x\" | grep -qiE 'a'; then\n",
            "          printf '%s' \"$x\" \\\n            | grep -Eq 'a'\n",
            "          node -e 'require(\"fs\")'\n",
            concat!("          /usr/bin/py", "thon3 -c 'import os'\n"),
            "          x | grep --quiet y\n",
        ] {
            assert!(!workflow_findings("w", bad).is_empty(), "passed: {bad}");
        }
        for good in [
            "          # node -e in prose\n",
            "          grep -q x <<< \"$y\"\n",
            "          x | grep -c y\n",
            "          node web/scripts/check.js\n",
            "          bad=$(git ls-files | grep -Ev '^x' || true)\n",
        ] {
            assert!(workflow_findings("w", good).is_empty(), "refused: {good}");
        }
    }

    #[test]
    fn content_that_no_extension_check_sees_is_refused() {
        let shebang = concat!("#!/usr/bin/env py", "thon3\nimport os\n");
        for (path, bytes) in [
            ("docs/x.md", &b"word\0 more"[..]),
            ("crates/a/src/x.rs", shebang.as_bytes()),
            ("crates/a/src/y.rs", &[0xff, 0xfe, b'a'][..]),
            ("docs/p.html", &b"<p onclick=go()>x</p>"[..]),
            ("docs/s.html", &b"<script>go()</script>"[..]),
        ] {
            assert!(!content_findings(path, bytes).is_empty(), "passed: {path}");
        }
        for (path, bytes) in [
            ("web/img.png", &b"\0\x89PNG"[..]),
            ("crates/a/src/lib.rs", &b"#![forbid(unsafe_code)]\n"[..]),
            ("docs/x.md", &b"<script> in prose is a .md, not a page"[..]),
            ("empty.md", &b""[..]),
        ] {
            assert!(content_findings(path, bytes).is_empty(), "refused: {path}");
        }
    }

    #[test]
