    #[test]
    fn compiled_roots_cover_every_target_shape() {
        let t: BTreeSet<String> = [
            "Cargo.toml",
            ".github/workflows/w.yml",
            ".github/tool.rs",
            "crates/a/build.rs",
            "crates/a/src/lib.rs",
            "crates/a/src/bin/x.rs",
            "crates/a/tests/t.rs",
            "crates/a/tests/common/mod.rs",
            "crates/a/benches/b.rs",
            "web/x.rs",
        ]
        .iter()
        .map(|s| (*s).to_owned())
        .collect();
        let read = |p: &str| match p {
            "Cargo.toml" => Some("[workspace]\nmembers = [\"crates/a\"]\n".to_owned()),
            ".github/workflows/w.yml" => Some("      - run: rustc .github/tool.rs\n".to_owned()),
            _ => None,
        };
        let r = compiled_roots(&t, &read).unwrap();
        assert!(r.contains(&"crates/a/tests/t.rs".to_owned()));
        assert!(!r.contains(&"crates/a/tests/common/mod.rs".to_owned()));
        assert!(!r.contains(&"web/x.rs".to_owned()));
        assert_eq!(r.len(), 6);
    }

    /// D-3692: a conventional path whose discovery the member's manifest
    /// turned off is not a root; an explicitly named target still is, and an
    /// overriding `[lib]` or `build` path takes the root's place.
    #[test]
    fn a_target_cargo_does_not_discover_is_not_a_root() {
        let t: BTreeSet<String> = [
            "Cargo.toml",
            "crates/a/Cargo.toml",
            "crates/a/build.rs",
            "crates/a/src/lib.rs",
            "crates/a/src/core.rs",
            "crates/a/src/main.rs",
            "crates/a/src/bin/x.rs",
            "crates/a/tests/t.rs",
            "crates/a/benches/b.rs",
            "crates/a/benches/ratio.rs",
            "crates/a/examples/e.rs",
            "crates/b/Cargo.toml",
            "crates/b/build.rs",
            "crates/b/src/lib.rs",
            "crates/b/tests/t.rs",
        ]
        .iter()
        .map(|s| (*s).to_owned())
        .collect();
        let read = |p: &str| {
            match p {
            "Cargo.toml" => {
                Some("[workspace]\nmembers = [\"crates/a\", \"crates/b\"]\n".to_owned())
            }
            "crates/a/Cargo.toml" => Some(
                "[package]\nname = \"a\"\nbuild = false\nautobins = false\nautotests = false\nautobenches = false\nautoexamples = false\n\n[lib]\npath = \"src/core.rs\"\n\n[[bench]]\nname = \"ratio\"\nharness = false\n"
                    .to_owned(),
            ),
            "crates/b/Cargo.toml" => Some("[package]\nname = \"b\"\n".to_owned()),
            _ => None,
        }
        };
        let r = compiled_roots(&t, &read).unwrap();
        assert_eq!(
            r,
            vec![
                "crates/a/benches/ratio.rs".to_owned(),
                "crates/a/src/core.rs".to_owned(),
                "crates/b/build.rs".to_owned(),
                "crates/b/src/lib.rs".to_owned(),
                "crates/b/tests/t.rs".to_owned(),
            ]
        );
    }

    // ---- audit-20261003 (D-1600..D-1619) ----

    #[test]
    fn a_step_that_swallows_or_skips_its_command_is_refused() {
        // hunt-ci-3: a line that RUNS the command but discards its verdict.
        for to in [
            "          cargo deny check || true\n",
            "          cargo deny check || :\n",
            "          cargo deny check; true\n",
            "          cargo deny check &\n",
            "          cargo deny check | tee log\n",
            "          if false; then\n          cargo deny check\n          fi\n",
            "          while false; do\n          cargo deny check\n          done\n",
            "          skip() {\n          cargo deny check\n          }\n",
            "          set +e\n          cargo deny check\n",
            "          cat <<EOF\n          cargo deny check\n          EOF\n",
        ] {
            let wf = WF.replacen("          cargo deny check\n", to, 1);
            assert!(step_runs(&wf, "cargo deny check").is_err(), "passed: {to}");
        }
        // A block that has CLOSED before the line does not hide it.
        let wf = WF.replacen(
            "          cargo deny check\n",
            "          if [ -n x ]; then\n            echo y\n          fi\n          cargo deny check\n",
            1,
        );
        assert_eq!(step_runs(&wf, "cargo deny check"), Ok(1));
    }

    /// P15-02, D-2513. Each script below kept `cargo deny check` from
    /// deciding its step, and the old `swallowed` returned None for every
    /// one: an earlier exit or return, an EXIT trap, a one-line function
    /// that shadows the command, and a `|| true` on a continuation line.
    #[test]
    fn swallowed_refuses_what_ends_or_replaces_the_script_first() {
        let lines = |s: &str| -> Vec<String> { s.lines().map(str::to_owned).collect() };
        for (script, why) in [
            ("exit 0\ncargo deny check\n", "follows `exit 0`"),
            ("exit\ncargo deny check\n", "follows `exit`"),
            ("exit $x\ncargo deny check\n", "follows `exit $x`"),
            ("return 0\ncargo deny check\n", "follows `return 0`"),
            (
                "[ -n \"$a\" ] || exit 0\ncargo deny check\n",
                "follows `exit 0`",
            ),
            ("{ exit 0; }\ncargo deny check\n", "follows `exit 0`"),
            ("exec true\ncargo deny check\n", "follows `exec true`"),
            ("trap 'exit 0' EXIT\ncargo deny check\n", "a `trap`"),
            ("trap 'exit 0' 0\ncargo deny check\n", "a `trap`"),
            ("cargo() { :; }\ncargo deny check\n", "`cargo()`"),
            (
                "cargo () { :; }\ncargo deny check\n",
                "a function definition",
            ),
            (
                "function cargo { :; }\ncargo deny check\n",
                "an `function` definition",
            ),
            (
                "alias cargo=true\ncargo deny check\n",
                "an `alias` definition",
            ),
            (
                "cargo deny check \\\n  || true\n",
                "discards its exit status",
            ),
            (
                "cargo deny check \\\n  --x \\\n  ; true\n",
                "discards its exit status",
            ),
            ("exit 0\nexit 1\ncargo deny check\n", "follows `exit 0`"),
        ] {
            let got = swallowed(&lines(script), "cargo deny check");
            assert!(
                got.as_deref().is_some_and(|g| g.contains(why)),
                "{script:?}: {got:?}"
            );
        }
        // A failing exit, before or after, and anything after the line,
        // leave it deciding the step; so does a continuation that adds an
        // argument.
        for script in [
            "x || { echo no; exit 1; }\ncargo deny check\n",
            "exit 255 || true\ncargo deny check\n",
            "cargo deny check\nexit 0\n",
            "cargo deny check\ntrap 'x' EXIT\n",
            "cargo deny check \\\n  --all-features\n",
            "echo results\ncargo deny check\n",
        ] {
            assert_eq!(
                swallowed(&lines(script), "cargo deny check"),
                None,
                "{script:?}"
            );
        }
        // The real form, through step_runs.
        let wf = WF.replacen(
            "          cargo deny check\n",
            "          cargo() { :; }\n          cargo deny check\n",
            1,
        );
        assert!(step_runs(&wf, "cargo deny check").is_err());
        assert_eq!(
            ends_the_script(&["exit", "256"]),
            Some("follows `exit 256`, which can end the script before it runs".to_owned())
        );
        assert!(ends_the_script(&["exit", "-1"]).is_some());
        assert_eq!(ends_the_script(&[]), None);
        assert!(ends_the_script(&["()"]).is_some());
        assert!(is_step_key("if: always()"));
        assert!(is_step_key("- name: Gate 3"));
        assert!(is_step_key("run: |"));
        assert!(is_step_key("run:"));
        assert!(!is_step_key("f() { :; }"));
        assert!(!is_step_key("exit 0"));
        assert!(!is_step_key("echo a:b"));
        assert!(!is_step_key("Gate: x"));
        assert_eq!(ends_the_script(&["f()x"]), None);
        assert_eq!(
            continued(&lines("a \\\nb \\\nc\nd\\")),
            vec!["a  b  c".to_owned(), "d".to_owned()]
        );
        assert_eq!(continued(&[]), Vec::<String>::new());
    }

    /// P15-03 and P15-06, D-2514. The probe condition was safe in any job,
    /// where `steps.probe` is null and the step is skipped on every run; and
    /// an `if:` on any step other than the four `step_runs` needles was read
    /// by nothing. Each case below passed the old code.
    #[test]
    fn workflow_refuses_a_skip_condition_on_any_gate_step() {
        let wf = "jobs:\n  build:\n    runs-on: x\n    steps:\n      - id: probe\n        run: x\n      - name: Gate 3\n        if: steps.probe.outputs.has_crates == 'true'\n        run: |\n          cargo deny check\n  complexity:\n    runs-on: x\n    steps:\n      - name: Gate 1 — extension allowlist\n        run: |\n          x\n  ci-ok:\n    needs: [build, complexity]\n    if: always()\n    steps:\n      - run: true\n";
        assert_eq!(condition_findings("w", wf), Vec::<String>::new());
        assert_eq!(step_runs(wf, "cargo deny check"), Ok(1));
        for (from, to) in [
            (
                "      - name: Gate 1 — extension allowlist\n",
                "      - name: Gate 1 — extension allowlist\n        if: false\n",
            ),
            (
                "      - name: Gate 1 — extension allowlist\n",
                "      - name: Gate 1 — extension allowlist\n        if: steps.probe.outputs.has_crates == 'true'\n",
            ),
            (
                "      - name: Gate 1 — extension allowlist\n",
                "      - name: Gate 1 — extension allowlist\n        \"if\": ${{ false }}\n",
            ),
            (
                "      - name: Gate 1 — extension allowlist\n",
                "      - if: github.run_attempt == 0\n        name: Gate 1 — extension allowlist\n",
            ),
            (
                "  complexity:\n    runs-on: x\n",
                "  complexity:\n    runs-on: x\n    if: github.run_attempt == 0\n",
            ),
            (
                "  complexity:\n    runs-on: x\n",
                "  complexity:\n    runs-on: x\n    if: steps.probe.outputs.has_crates == 'true'\n",
            ),
            (
                "  build:\n    runs-on: x\n",
                "  build:\n    runs-on: x\n    if: steps.probe.outputs.has_crates == 'true'\n",
            ),
            (
                "        if: steps.probe.outputs.has_crates == 'true'\n",
                "        if: steps.probe.outputs.has_crates == 'false'\n",
            ),
            ("    if: always()\n", "    if: false\n"),
        ] {
            let planted = wf.replacen(from, to, 1);
            assert_ne!(planted, wf, "the plant did not apply: {to}");
            assert!(
                !condition_findings("w", &planted).is_empty(),
                "passed: {to}"
            );
            assert!(!workflow_findings("w", &planted).is_empty(), "passed: {to}");
        }
        // The probe condition moved to a step of another job fails
        // step_runs too.
        let moved = wf.replacen("  build:\n", "  builder:\n", 1).replacen(
            "    needs: [build, complexity]\n",
            "    needs: [builder, complexity]\n",
            1,
        );
        assert!(step_runs(&moved, "cargo deny check").is_err());
        assert!(condition_is_safe(
            "steps.probe.outputs.has_crates == 'true'",
            true
        ));
        assert!(!condition_is_safe(
            "steps.probe.outputs.has_crates == 'true'",
            false
        ));
        for c in ["always()", "${{ success() }}", "!cancelled()", "'always()'"] {
            assert!(condition_is_safe(c, false), "{c}");
        }
        for c in ["", "false", "true", "'", "always() && false", "failure()"] {
            assert!(!condition_is_safe(c, true), "{c}");
        }
        // The real workflows hold no unsafe condition.
        for (p, real) in [
            ("ci.yml", include_str!("workflows/ci.yml")),
            ("auto-merge.yml", include_str!("workflows/auto-merge.yml")),
            ("main-check.yml", include_str!("workflows/main-check.yml")),
        ] {
            assert_eq!(condition_findings(p, real), Vec::<String>::new());
        }
    }

    /// P15-04, D-2515. YAML reads a quoted key and a key in a flow mapping
    /// as the key itself; the old prefix rule saw neither.
    #[test]
    fn a_quoted_or_flow_mapping_continue_on_error_is_refused() {
        for bad in [
            "        \"continue-on-error\": true\n",
            "        'continue-on-error': true\n",
            "      - { name: x, continue-on-error: true, run: cargo deny check }\n",
            "      - {continue-on-error: true}\n",
            "    \"continue-on-error\" : true\n",
        ] {
            let found = workflow_findings("w", bad);
            assert!(
                found.iter().any(|f| f.ends_with(": continue-on-error")),
                "passed: {bad}: {found:?}"
            );
        }
        let flow = workflow_findings("w", "      - { name: x, run: y }\n");
        assert!(flow.iter().any(|f| f.contains("flow mapping")), "{flow:?}");
        // `with: { .. }` is a value, not a step.
        for good in [
            "        with: { fetch-depth: 0 }\n",
            "        continue-on-errorx: 1\n",
            "        x: continue-on-error\n",
        ] {
            assert!(workflow_findings("w", good).is_empty(), "refused: {good}");
        }
        // step_runs reads the quoted key at its level too.
        for key in ["\"continue-on-error\"", "'continue-on-error'", "\"if\""] {
            let v = if key.contains("if") { "false" } else { "true" };
            let wf = WF.replacen(
                "      - name: Gate 3\n",
                &format!("      - name: Gate 3\n        {key}: {v}\n"),
                1,
            );
            assert!(step_runs(&wf, "cargo deny check").is_err(), "{key}");
        }
        assert_eq!(key_value("\"if\": x", "if"), Some("x"));
        assert_eq!(key_value("'if' : x ", "if"), Some("x"));
        assert_eq!(key_value("\"if': x", "if"), None);
        assert_eq!(key_value("ifx: x", "if"), None);
        assert_eq!(key_value("if", "if"), None);
        assert_eq!(key_value("", "if"), None);
    }

    const AGG: &str = "jobs:\n  a:\n    runs-on: x\n  b:\n    runs-on: x\n  ci-ok:\n    name: ci-ok\n    needs: [a, b]\n    if: always()\n    steps:\n      - name: Verify every gate went green\n        # a comment is not a line of the step\n        env:\n          RESULTS: ${{ join(needs.*.result, ' ') }}\n        run: |\n          set -euo pipefail\n          echo \"results: ${RESULTS}\"\n          if [ -z \"${RESULTS}\" ]; then\n            echo \"no gate reported a result at all — refusing to call that green\"\n            exit 1\n          fi\n\n          for x in ${RESULTS}; do\n            [ \"$x\" = \"success\" ] || { echo \"a gate did not pass: $x\"; exit 1; }\n          done\n          echo \"all gates green\"\n";

    /// P15-05, D-2516. Each plant below left the three checked lines in
    /// place, so the old aggregator rule passed every one of them while
    /// ci-ok went green whatever the jobs returned.
    #[test]
    fn aggregator_refuses_any_line_outside_the_exact_ci_ok_body() {
        assert_eq!(aggregator_findings(AGG), Vec::<String>::new());
        let lp = "          for x in ${RESULTS}; do\n";
        for (from, to) in [
            (lp, &*format!("          RESULTS=success\n{lp}")),
            (lp, &*format!("          exit 0\n{lp}")),
            (lp, &*format!("          true\n{lp}")),
            ("          set -euo pipefail\n", ""),
            ("          echo \"all gates green\"\n", ""),
            (
                "          echo \"all gates green\"\n",
                "          echo \"all gates green\"\n          echo extra\n",
            ),
            (
                "          set -euo pipefail\n          echo \"results: ${RESULTS}\"\n",
                "          echo \"results: ${RESULTS}\"\n          set -euo pipefail\n",
            ),
            ("        env:\n", "        env:\n          BASH_ENV: ./x\n"),
            ("          exit 1\n", "          exit 0\n"),
            (
                "      - name: Verify every gate went green\n",
                "      - name: Something else\n",
            ),
            ("        run: |\n", "        run: |-\n"),
        ] {
            let wf = AGG.replacen(from, to, 1);
            assert_ne!(wf, AGG, "the plant did not apply: {to}");
            let found = aggregator_findings(&wf);
            assert!(
                found
                    .iter()
                    .any(|f| f.contains("is not exactly the success-only check")),
                "passed: {to}: {found:?}"
            );
        }
        // A second step, before or after, is refused by count.
        let second = format!("{AGG}      - run: true\n");
        assert!(
            aggregator_findings(&second)
                .iter()
                .any(|f| f == "ci-ok must hold exactly one step; found 2")
        );
        let first = AGG.replacen(
            "      - name: Verify",
            "      - run: exit 0\n      - name: Verify",
            1,
        );
        assert!(
            aggregator_findings(&first)
                .iter()
                .any(|f| f == "ci-ok must hold exactly one step; found 2")
        );
        let none = AGG.split("    steps:\n").next().unwrap().to_owned();
        assert!(
            aggregator_findings(&none)
                .iter()
                .any(|f| f == "ci-ok must hold exactly one step; found 0")
        );
        // Indentation, trailing spaces and blank or comment lines are not
        // lines of the step.
        let spaced = AGG.replacen(
            "          done\n",
            "              done   \n\n          # note\n",
            1,
        );
        assert_eq!(aggregator_findings(&spaced), Vec::<String>::new());
        // The real workflow's ci-ok is the constant, line for line.
        let real = include_str!("workflows/ci.yml");
        assert_eq!(aggregator_findings(real), Vec::<String>::new());
    }

    #[test]
    fn the_aggregator_needs_every_job_runs_always_and_accepts_only_success() {
        // hunt-ci-4.
        assert_eq!(aggregator_findings(AGG), Vec::<String>::new());
        for (from, to) in [
            ("    needs: [a, b]\n", "    needs: [a]\n"),
            ("    needs: [a, b]\n", "    needs: [a, b, gone]\n"),
            ("    if: always()\n", ""),
            ("    if: always()\n", "    if: success()\n"),
            (
                "    if: always()\n",
                "    if: always()\n    continue-on-error: true\n",
            ),
            ("[ \"$x\" = \"success\" ]", "[ \"$x\" != \"failure\" ]"),
            ("join(needs.*.result, ' ')", "join(needs.a.result, ' ')"),
            ("  ci-ok:\n", "  ok:\n"),
        ] {
            let wf = AGG.replacen(from, to, 1);
            assert!(!aggregator_findings(&wf).is_empty(), "passed: {to}");
        }
        // A job added without being listed is the case the gate exists for.
        let wf = AGG.replacen("  ci-ok:\n", "  c:\n    runs-on: x\n  ci-ok:\n", 1);
        assert!(!aggregator_findings(&wf).is_empty());
    }

